import React, { useEffect, useState } from 'react';

const blank = { title: '', description: '', priority: 'Medium', category: '', deadline: '' };

export default function TaskForm({ onSubmit, editing, onUpdate, onCancel }) {
  const [form, setForm] = useState(blank);

  useEffect(() => {
    if (editing) {
      setForm({
        title: editing.title || '',
        description: editing.description || '',
        priority: editing.priority || 'Medium',
        category: editing.category || '',
        deadline: editing.deadline ? new Date(editing.deadline).toISOString().slice(0, 16) : '',
      });
    } else {
      setForm(blank);
    }
  }, [editing]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((s) => ({ ...s, [name]: value }));
  };

  const submit = (e) => {
    e.preventDefault();
    if (!form.title.trim()) {
      alert('Title is required');
      return;
    }

    const payload = {
      title: form.title.trim(),
      description: form.description.trim() || undefined,
      priority: form.priority,
      category: form.category.trim() || undefined,
      deadline: form.deadline ? new Date(form.deadline).toISOString() : undefined,
    };

    if (editing) {
      onUpdate(editing.id, payload);
    } else {
      onSubmit(payload);
      setForm(blank);
    }
  };

  return (
    <form onSubmit={submit} className="bg-white p-4 rounded shadow">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <input
          name="title"
          value={form.title}
          onChange={handleChange}
          placeholder="Title"
          required
          className="col-span-2 p-2 border rounded"
        />

        <select name="priority" value={form.priority} onChange={handleChange} className="p-2 border rounded">
          <option>Low</option>
          <option>Medium</option>
          <option>High</option>
        </select>

        <input
          name="category"
          value={form.category}
          onChange={handleChange}
          placeholder="Category"
          className="p-2 border rounded col-span-1 md:col-span-3"
        />

        <input
          name="deadline"
          type="datetime-local"
          value={form.deadline}
          onChange={handleChange}
          className="p-2 border rounded col-span-1 md:col-span-3"
        />

        <textarea
          name="description"
          value={form.description}
          onChange={handleChange}
          placeholder="Description"
          className="p-2 border rounded col-span-1 md:col-span-3"
        />
      </div>

      <div className="mt-3 flex gap-2">
        <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded">
          {editing ? 'Update' : 'Add Task'}
        </button>
        {editing && (
          <button type="button" onClick={onCancel} className="px-4 py-2 bg-gray-300 rounded">
            Cancel
          </button>
        )}
      </div>
    </form>
  );
}
